    44	 /* This is not an ERR message, the connection is not closed afterwards */
    45	static UA_StatusCode
    46	sendServiceFault(UA_SecureChannel *channel, const UA_ByteString *msg,
    47	                 size_t offset, const UA_DataType *responseType,
    48	                 UA_UInt32 requestId, UA_StatusCode error) {
    49	    UA_RequestHeader requestHeader;
    50	    UA_StatusCode retval = UA_RequestHeader_decodeBinary(msg, &offset, &requestHeader);
    51	    if(retval != UA_STATUSCODE_GOOD)
    52	        return retval;
    53	    UA_STACKARRAY(UA_Byte, response, responseType->memSize);
    54	    UA_init(response, responseType);
    55	    UA_ResponseHeader *responseHeader = (UA_ResponseHeader*)response;
    56	    responseHeader->requestHandle = requestHeader.requestHandle;
    57	    responseHeader->timestamp = UA_DateTime_now();
    58	    responseHeader->serviceResult = error;
    59	
    60	    // Send error message. Message type is MSG and not ERR, since we are on a securechannel!
    61	    retval = UA_SecureChannel_sendSymmetricMessage(channel, requestId, UA_MESSAGETYPE_MSG,
    62	                                                   response, responseType);
    63	
    64	    UA_RequestHeader_deleteMembers(&requestHeader);
    65	    UA_LOG_DEBUG(channel->securityPolicy->logger, UA_LOGCATEGORY_SERVER,
    66	                 "Sent ServiceFault with error code %s", UA_StatusCode_name(error));
    67	    return retval;
    68	}
