    53	    UA_STACKARRAY(UA_Byte, response, responseType->memSize);
    54	    UA_init(response, responseType);
    55	    UA_ResponseHeader *responseHeader = (UA_ResponseHeader*)response;
    56	    responseHeader->requestHandle = requestHeader.requestHandle;
    57	    responseHeader->timestamp = UA_DateTime_now();
    58	    responseHeader->serviceResult = error;
