   354	        *buf_end -= UA_SecurityPolicy_getRemoteAsymEncryptionBufferLengthOverhead(securityPolicy,
   355	                                                                                  channel->channelContext,
   356	                                                                                  potentialEncryptionMaxSize);
   357	    }
