   170	static UA_StatusCode
   171	UA_SecureChannel_generateLocalKeys(const UA_SecureChannel *const channel,
   172	                                   const UA_SecurityPolicy *const securityPolicy) {
   173	    UA_LOG_TRACE_CHANNEL(securityPolicy->logger, channel, "Generating new local keys");
   174	    const UA_SecurityPolicyChannelModule *channelModule = &securityPolicy->channelModule;
   175	    const UA_SecurityPolicySymmetricModule *symmetricModule = &securityPolicy->symmetricModule;
   176	    const UA_SecurityPolicyCryptoModule *const cryptoModule = &securityPolicy->symmetricModule.cryptoModule;
   177	    /* Symmetric key length */
   178	    size_t encryptionKeyLength =
   179	        cryptoModule->encryptionAlgorithm.getLocalKeyLength(securityPolicy, channel->channelContext);
   180	    size_t encryptionBlockSize =
   181	        cryptoModule->encryptionAlgorithm.getLocalBlockSize(securityPolicy, channel->channelContext);
   182	    size_t signingKeyLength =
   183	        cryptoModule->signatureAlgorithm.getLocalKeyLength(securityPolicy, channel->channelContext);
   184	    const size_t bufSize = encryptionBlockSize + signingKeyLength + encryptionKeyLength;
   185	    UA_STACKARRAY(UA_Byte, bufBytes, bufSize);
   186	    UA_ByteString buffer = {bufSize, bufBytes};
   187	
   188	    /* Local keys */
   189	    UA_StatusCode retval = symmetricModule->generateKey(securityPolicy, &channel->remoteNonce,
   190	                                                        &channel->localNonce, &buffer);
   191	    if(retval != UA_STATUSCODE_GOOD)
   192	        return retval;
   193	    const UA_ByteString localSigningKey = {signingKeyLength, buffer.data};
   194	    const UA_ByteString localEncryptingKey = {encryptionKeyLength,
   195	                                              buffer.data + signingKeyLength};
   196	    const UA_ByteString localIv = {encryptionBlockSize,
   197	                                   buffer.data + signingKeyLength +
   198	                                   encryptionKeyLength};
   199	
   200	    retval = channelModule->setLocalSymSigningKey(channel->channelContext, &localSigningKey);
   201	    if(retval != UA_STATUSCODE_GOOD)
   202	        return retval;
   203	
   204	    retval = channelModule->setLocalSymEncryptingKey(channel->channelContext, &localEncryptingKey);
   205	    if(retval != UA_STATUSCODE_GOOD)
   206	        return retval;
   207	
   208	    retval = channelModule->setLocalSymIv(channel->channelContext, &localIv);
   209	    if(retval != UA_STATUSCODE_GOOD)
   210	        return retval;
   211	
   212	    return retval;
   213	}
