   215	static UA_StatusCode
   216	UA_SecureChannel_generateRemoteKeys(const UA_SecureChannel *const channel,
   217	                                    const UA_SecurityPolicy *const securityPolicy) {
   218	    UA_LOG_TRACE_CHANNEL(securityPolicy->logger, channel, "Generating new remote keys");
   219	    const UA_SecurityPolicyChannelModule *channelModule = &securityPolicy->channelModule;
   220	    const UA_SecurityPolicySymmetricModule *symmetricModule = &securityPolicy->symmetricModule;
   221	    const UA_SecurityPolicyCryptoModule *const cryptoModule = &securityPolicy->symmetricModule.cryptoModule;
   222	    /* Symmetric key length */
   223	    size_t encryptionKeyLength =
   224	        cryptoModule->encryptionAlgorithm.getRemoteKeyLength(securityPolicy, channel->channelContext);
   225	    size_t encryptionBlockSize =
   226	        cryptoModule->encryptionAlgorithm.getRemoteBlockSize(securityPolicy, channel->channelContext);
   227	    size_t signingKeyLength =
   228	        cryptoModule->signatureAlgorithm.getRemoteKeyLength(securityPolicy, channel->channelContext);
   229	    const size_t bufSize = encryptionBlockSize + signingKeyLength + encryptionKeyLength;
   230	    UA_STACKARRAY(UA_Byte, bufBytes, bufSize);
   231	    UA_ByteString buffer = {bufSize, bufBytes};
   232	
   233	    /* Remote keys */
   234	    UA_StatusCode retval = symmetricModule->generateKey(securityPolicy, &channel->localNonce,
   235	                                                        &channel->remoteNonce, &buffer);
   236	    if(retval != UA_STATUSCODE_GOOD)
   237	        return retval;
   238	    const UA_ByteString remoteSigningKey = {signingKeyLength, buffer.data};
   239	    const UA_ByteString remoteEncryptingKey = {encryptionKeyLength,
   240	                                               buffer.data + signingKeyLength};
   241	    const UA_ByteString remoteIv = {encryptionBlockSize,
   242	                                    buffer.data + signingKeyLength +
   243	                                    encryptionKeyLength};
   244	
   245	    retval = channelModule->setRemoteSymSigningKey(channel->channelContext, &remoteSigningKey);
   246	    if(retval != UA_STATUSCODE_GOOD)
   247	        return retval;
   248	
   249	    retval = channelModule->setRemoteSymEncryptingKey(channel->channelContext, &remoteEncryptingKey);
   250	    if(retval != UA_STATUSCODE_GOOD)
   251	        return retval;
   252	
   253	    retval = channelModule->setRemoteSymIv(channel->channelContext, &remoteIv);
   254	    if(retval != UA_STATUSCODE_GOOD)
   255	        return retval;
   256	
   257	    return retval;
   258	}
