   260	UA_StatusCode
   261	UA_SecureChannel_generateNewKeys(UA_SecureChannel *channel) {
   262	    UA_StatusCode retval = UA_SecureChannel_generateLocalKeys(channel, channel->securityPolicy);
   263	    if(retval != UA_STATUSCODE_GOOD)
   264	        return retval;
   265	
   266	    retval = UA_SecureChannel_generateRemoteKeys(channel, channel->securityPolicy);
   267	    if(retval != UA_STATUSCODE_GOOD)
   268	        return retval;
   269	
   270	    return retval;
