   284	UA_StatusCode
   285	UA_SecureChannel_revolveTokens(UA_SecureChannel *channel) {
   286	    if(channel->nextSecurityToken.tokenId == 0) // no security token issued
   287	        return UA_STATUSCODE_BADSECURECHANNELTOKENUNKNOWN;
   288	
   289	    //FIXME: not thread-safe ???? Why is this not thread safe?
   290	    UA_ChannelSecurityToken_deleteMembers(&channel->previousSecurityToken);
   291	    UA_ChannelSecurityToken_copy(&channel->securityToken, &channel->previousSecurityToken);
   292	
   293	    UA_ChannelSecurityToken_deleteMembers(&channel->securityToken);
   294	    UA_ChannelSecurityToken_copy(&channel->nextSecurityToken, &channel->securityToken);
   295	
   296	    UA_ChannelSecurityToken_deleteMembers(&channel->nextSecurityToken);
   297	    UA_ChannelSecurityToken_init(&channel->nextSecurityToken);
   298	
   299	    /* remote keys are generated later on */
   300	    return UA_SecureChannel_generateLocalKeys(channel, channel->securityPolicy);
   301	}
