   324	static size_t
   325	calculateAsymAlgSecurityHeaderLength(const UA_SecureChannel *channel) {
   326	    size_t asymHeaderLength = UA_ASYMMETRIC_ALG_SECURITY_HEADER_FIXED_LENGTH +
   327	                              channel->securityPolicy->policyUri.length;
   328	    if(channel->securityMode == UA_MESSAGESECURITYMODE_SIGN ||
   329	       channel->securityMode == UA_MESSAGESECURITYMODE_SIGNANDENCRYPT) {
   330	        /* OPN is always encrypted even if mode sign only */
   331	        asymHeaderLength += 20; /* Thumbprints are always 20 byte long */
   332	        asymHeaderLength += channel->securityPolicy->localCertificate.length;
   333	    }
   334	    return asymHeaderLength;
   335	}
