   338	hideBytesAsym(const UA_SecureChannel *channel, UA_Byte **buf_start, const UA_Byte **buf_end) {
   339	    const UA_SecurityPolicy *securityPolicy = channel->securityPolicy;
   340	    *buf_start += UA_SECURE_CONVERSATION_MESSAGE_HEADER_LENGTH + UA_SEQUENCE_HEADER_LENGTH;
   341	
   342	    /* Add the SecurityHeaderLength */
